<?php
defined('ABSPATH') || exit;
/** A registered issued document anchors one native historical sale; its fiscal payload stays immutable. */
final class GE_Work_History_Invoices {
    const META='_ge_historical_invoice_execution';
    public static function fiscal_hash($doc){unset($doc['order_id']);return hash('sha256',wp_json_encode($doc));}
    public static function source($key){$s=GE_Work_History_Commercial::source($key);$r=$s['row'];if($r['order_id'] || $r['quote_id'] || $r['commercial']!=='performed' || $r['production']!=='completed')throw new DomainException('Esta confirmación requiere otra ficha de origen.');return array('revision'=>$s['revision'],'row'=>$r,'expected_fingerprints'=>array());}
    public static function document($id,$source){$d=GE_WTP_Customer_Invoices::resolve('invoice:'.absint($id),get_current_user_id());GE_Work_History_Storage::check();if(is_wp_error($d))throw new DomainException($d->get_error_message());$r=$source['row'];if(($d['type']??'')!=='factura' || !empty($d['superseded']) || !empty($d['superseded_at']) || !empty($d['replaced_by']))throw new DomainException('El comprobante no es una factura vigente.');if(!preg_match('/(\d{5}-\d{8})/',$r['reference'],$m) || $m[1]!==$d['number'])throw new DomainException('El número de factura no coincide con la confirmación.');$amount=GE_WTP_Quote_Balance::cents($d['amount']);if($amount<=0 || $d['currency']!==$r['currency'] || ($r['reference_cents']!==null && $amount!==$r['reference_cents']) || ($r['performed_cents']!==null && $amount!==$r['performed_cents']))throw new DomainException('El importe o moneda no coincide con la confirmación.');return $d;}
    public static function valid($order,$source){$p=$order->get_meta(self::META,true);if(!is_array($p) || empty($p['actor']) || ($p['source_revision']??'')!==$source['revision'] || ($p['source_key']??'')!==$source['row']['key'])return false;$d=self::document($p['invoice_id'],$source);return (int)get_post_meta($p['invoice_id'],'_ge_historical_order_id',true)===$order->get_id() && (int)$d['customer_id']===$order->get_customer_id() && ($p['document_hash']??'')===self::fiscal_hash($d);}
    public static function create($key,$invoice_id,$details=array()){
        if(!GE_Work_Historical_Reconciliation::allowed())throw new RuntimeException('Acceso denegado.');$source=self::source($key);$expected_source=$source;$doc=self::document($invoice_id,$source);$root=absint($doc['order_id']??0);$quote=absint($doc['quote_id']??0);$lock='ge_commercial_reconcile_'.($quote?:'invoice_'.$invoice_id);if(!GE_Work_Finance::lock($lock))throw new RuntimeException('El comprobante está siendo conciliado.');$started=false;$order=null;
        try{
            GE_Work_History_Storage::begin($root,array(),array_filter(array(absint($invoice_id),$quote)));$started=true;$source=self::source($key);if($source!==$expected_source)throw new DomainException('Cambió la confirmación; revisá el vínculo antes de repetir.');$doc=self::document($invoice_id,$source);$existing=absint(get_post_meta($invoice_id,'_ge_historical_order_id',true));GE_Work_History_Storage::check();if($existing){$order=wc_get_order($existing);if(!$order || !self::valid($order,$source))throw new DomainException('El comprobante ya tiene otro vínculo; revisá su ficha.');GE_Work_History_Storage::commit();$started=false;return $order;}
            if((int)($doc['order_id']??0)!==$root || (int)($doc['quote_id']??0)!==$quote)throw new DomainException('Cambió el vínculo del comprobante.');
            $total=GE_WTP_Quote_Balance::cents($doc['amount']);if($root){$order=wc_get_order($root);GE_Work_History_Storage::check();}
            elseif($quote){$q=GE_WTP_Commercial_Quotes::get($quote,get_current_user_id());GE_Work_History_Storage::check();if(is_wp_error($q) || (int)$q['customer_id']!==(int)$doc['customer_id'] || (int)$q['snapshot']['total_cents']!==$total || ($q['snapshot']['currency']??'ARS')!==$doc['currency'])throw new DomainException('El presupuesto vinculado no coincide con la factura.');$order=GE_WTP_Commercial_Checkout::historical_order_from_quote($quote);if(is_wp_error($order))throw new DomainException($order->get_error_message());}
            else{
                $net=$details['net_cents']??null;$tax=$details['tax_cents']??null;$qty=$details['quantity']??0;$description=trim((string)($details['description']??''));if(!is_int($net)||!is_int($tax)||$net<=0||$tax<0||$net+$tax!==$total||!is_numeric($qty)||(float)$qty<=0||!$description||empty($details['verified_against_document']))throw new DomainException('Verificá descripción, cantidad, neto e IVA contra el comprobante.');$rate=absint(get_option('ge_historical_tax_rate_id',0));GE_Work_History_Storage::check();if($tax && !$rate)throw new DomainException('Falta la tasa de IVA del pedido.');
                $order=wc_create_order(array('customer_id'=>(int)$doc['customer_id']));if(is_wp_error($order))throw new RuntimeException('No se pudo crear el pedido histórico.');$order->set_currency($doc['currency']);$order->set_created_via('ge_historical_invoice');$receiver=$doc['receiver']??array();$order->set_billing_company($receiver['legal_name']??'');$order->set_billing_address_1($receiver['fiscal_address']??'');$order->update_meta_data('_ge_billing_profile_snapshot',$receiver);$order->update_meta_data('_ge_billing_profile_id',$doc['profile_id']??'');
                $item=new WC_Order_Item_Product();$item->set_name($description);$item->set_quantity($qty);$item->set_subtotal(GE_WTP_Quote_Balance::decimal($net));$item->set_total(GE_WTP_Quote_Balance::decimal($net));$item->update_meta_data('_ge_item_status','pending');if($tax)$item->set_taxes(array('total'=>array($rate=>GE_WTP_Quote_Balance::decimal($tax)),'subtotal'=>array($rate=>GE_WTP_Quote_Balance::decimal($tax))));$order->add_item($item);if($tax){$tax_item=new WC_Order_Item_Tax();$tax_item->set_rate_id($rate);$tax_item->set_label('IVA según factura emitida');$tax_item->set_tax_total(GE_WTP_Quote_Balance::decimal($tax));$order->add_item($tax_item);}$order->calculate_totals(false);$order->set_cart_tax(GE_WTP_Quote_Balance::decimal($tax));$order->set_total(GE_WTP_Quote_Balance::decimal($total));$order->save();GE_Work_History_Storage::check();
            }
            if(!$order || $order->get_customer_id()!==(int)$doc['customer_id'] || $order->get_currency()!==$doc['currency'] || GE_WTP_Quote_Balance::cents(wc_format_decimal($order->get_total(),2))!==$total)throw new DomainException('El pedido no coincide con la factura.');
            $proof=array('invoice_id'=>(int)$invoice_id,'document_hash'=>self::fiscal_hash($doc),'source_revision'=>$source['revision'],'source_key'=>$key,'actor'=>get_current_user_id(),'recorded_at'=>gmdate('c'),'details'=>$details,'created_new'=>!$root);$order->update_meta_data(self::META,$proof);$order->update_meta_data('_ge_work_label',$source['row']['customer']);GE_Work_History_Storage::save_order_meta($order);GE_Work_History_Storage::check();update_post_meta($invoice_id,'_ge_historical_order_id',$order->get_id());GE_Work_History_Storage::check();$linked=$doc;unset($linked['ref']);$linked['order_id']=$order->get_id();update_post_meta($invoice_id,GE_WTP_Customer_Invoices::META,$linked);GE_Work_History_Storage::check();add_post_meta($invoice_id,'_ge_invoice_audit',array('action'=>'historical_work_linked','actor'=>get_current_user_id(),'at'=>gmdate('c'),'before_order_id'=>$root,'after_order_id'=>$order->get_id(),'fiscal_hash'=>$proof['document_hash']));GE_Work_History_Storage::check();GE_Work_History_Storage::commit();$started=false;if($quote && class_exists('GE_CRM'))GE_CRM::quote_meta(0,$quote,GE_WTP_Commercial_Quotes::ORDER_META,$order->get_id());GE_Work_Finance::clear_order_cache($order->get_id());$order=wc_get_order($order->get_id());$order->read_meta_data(true);return $order;
        }catch(Throwable $e){if($started)GE_Work_History_Storage::abort();if($order instanceof WC_Order)GE_Work_Finance::clear_order_cache($order->get_id());clean_post_cache($invoice_id);if($quote)clean_post_cache($quote);throw $e;}finally{GE_Work_Finance::unlock($lock);}
    }
    public static function render($doc){if(!GE_Work_Historical_Reconciliation::allowed() || !preg_match('/^invoice:(\d+)$/D',$doc['ref']??'',$m))return;$s=get_option('ge_work_reconciliation_v1',array());if(empty($s['revisions']))return;$latest=end($s['revisions']);foreach($latest['rows'] as $r){if($r['order_id']||$r['quote_id']||$r['production']!=='completed'||!str_contains($r['reference'],$doc['number']))continue;echo '<details><summary>Conciliar trabajo histórico de esta factura</summary><form class="ge-admin-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ge_finance_work_history_invoice"><input type="hidden" name="source_key" value="'.esc_attr($r['key']).'"><input type="hidden" name="invoice_id" value="'.absint($m[1]).'">';wp_nonce_field('ge_finance_work_history_invoice_'.$m[1]);if(empty($doc['order_id'])&&empty($doc['quote_id'])){echo '<label>Trabajo realizado<input name="description" required></label><label>Cantidad<input name="quantity" type="number" min="0.01" step="0.01" required></label><label>Neto del comprobante<input name="net" required></label><label>IVA del comprobante<input name="tax" required></label><label><input type="checkbox" name="verified" value="1" required> Verifiqué estos datos contra el PDF.</label>';}echo '<p>Se vinculará una única venta real a este documento. No se emite factura ni se registra un recibo por el texto impreso del comprobante.</p><button class="ge-staff-button">Crear o vincular el trabajo histórico</button></form></details>';break;}}
    public static function handle(){if(!GE_Work_Historical_Reconciliation::allowed())GE_Work_Historical_Reconciliation::deny();$id=absint($_POST['invoice_id']??0);check_admin_referer('ge_finance_work_history_invoice_'.$id);try{$details=array('net_cents'=>GE_WTP_Quote_Balance::cents((string)($_POST['net']??'0')),'tax_cents'=>GE_WTP_Quote_Balance::cents((string)($_POST['tax']??'0')),'quantity'=>sanitize_text_field($_POST['quantity']??''),'description'=>sanitize_text_field($_POST['description']??''),'verified_against_document'=>!empty($_POST['verified']));$o=self::create(sanitize_key($_POST['source_key']??''),$id,$details);}catch(Throwable $e){wp_die(esc_html($e->getMessage()),'',array('response'=>409));}wp_safe_redirect(add_query_arg(array('section'=>'orders','order_id'=>$o->get_id()),home_url('/gestion/')));exit;}
}
add_action('admin_post_ge_finance_work_history_invoice',array('GE_Work_History_Invoices','handle'));add_action('admin_post_nopriv_ge_finance_work_history_invoice',array('GE_Work_Historical_Reconciliation','deny'));
